import {metrics,actors,actorDistance,shutterText,distanceText} from './physics.mjs';
export function stateRows(state){const m=metrics(state),s=m.s;return [
 ['Kulisse',s.clearBackdrop?'Freier Hintergrund':'Bäume im Hof'],['Pupillenform',({circle:'Rund',iris:'Iris',heart:'Herzmaske',bat:'Fledermausmaske'})[s.pupilShape]],['Lamellen',String(s.bladeCount)],['Gerundete Lamellen',s.roundedBlades?'an':'aus'],['Lichtpunkte',s.bokehLights?'an':'aus'],['Format',m.sensor.name],['Bauart',s.body==='dslr'?'DSLR':'Spiegellos'],['Modus',s.mode],['Brennweite',`${s.focal.toFixed(1)} mm`],['Blende',`ƒ/${Number(s.aperture.toFixed(1))}`],['Zeit',shutterText(s.time)],['ISO',`${Math.round(s.iso)}`],['Fokus',distanceText(s.focus)],['Auto-ISO',s.autoISO||s.mode==='P'?'an':'aus'],['Auto-Weißabgleich',s.autoWB?'an':'aus'],['Ausschnittssperre',s.matchFrame?'an':'aus'],['Autofokus',s.autoFocus?actors[s.afTarget].name:'aus'],['Szenenhelligkeit',`${s.ev.toFixed(1)} EV₁₀₀`],['Lichtfarbe',`${s.temperature} K`],['Weißabgleich',`${Math.round(s.wb)} K`],['ND',`${s.nd} EV`],['Korrektur',`${s.comp.toFixed(1)} EV`],['Sensorauflösung',`${s.mp} MP`],['Gehen',`${s.speed.toFixed(1)} m/s`],['Winken',`${s.waveSpeed.toFixed(1)} m/s`],['Balltempo',`${s.ballSpeed.toFixed(1)} m/s`],['Flugtempo',`${s.birdSpeed.toFixed(1)} m/s`],['Lampe',s.lampOn?'an':'aus'],['Fensterlicht',s.windowsOn?'an':'aus'],['Lampentyp',s.lampType==='spot'?'Spot':'Straßenlaterne'],['Spotrichtung',`${s.lampAngle}°`],['Lampenstärke',`${s.lampEV} EV₁₀₀`],['Kamera zurück',`${s.cameraBack.toFixed(1)} m`],...Object.entries(actors).filter(([id])=>id!=='camera').flatMap(([id,a])=>[[`Abstand ${a.name}`,distanceText(actorDistance(s,id))],...(a.x?[[`${a.name} seitlich`,`${s[a.x].toFixed(1)} m`]]:[])]),['Kamera seitlich',`${s.cameraX.toFixed(1)} m`],['Stativ',s.tripod?'an':'aus'],['Stabilisierung',s.stabilization?'an':'aus'],['Porträteffekt',s.portrait?'an':'aus'],['Schärfemaßstab',s.cocMode==='pixel'?'2 Pixel':'Diagonale / 1500'],['Belichtungsabweichung',`${m.offset.toFixed(2)} EV`],['Licht pro Fläche',`${m.physical.toFixed(3)}×`],['Schärfebereich',`${distanceText(m.near)} – ${distanceText(m.far)}`]
 ];}
export function comparisonRows(a,b){const first=new Map(stateRows(a));return stateRows(b).filter(([key,value])=>first.get(key)!==value).map(([key,value])=>({key,a:first.get(key),b:value}));}
